#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>

// Helper function to check the file size
void check_size(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        fprintf(stderr, "Current file size: %ld bytes\n", (long)st.st_size);
    } else {
        perror("stat failed");
    }
}

int main() {
    const char *filepath = "/tmp/test_trunc.dat";
    int fd;
    off_t target_len;

    // 1. Create file and write 20 bytes of data
    fd = open(filepath, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }
    if (write(fd, "0123456789ABCDEFGHIJ", 20) != 20) {
        perror("write");
        close(fd); unlink(filepath); return EXIT_FAILURE;
    }
    fprintf(stderr, "--- Initial State (20 bytes) ---\n");
    check_size(filepath);

    // 2. Use ftruncate to shrink the file (using the FD)
    target_len = 10;
    if (ftruncate(fd, target_len) == -1) {
        perror("ftruncate shrink failed");
        close(fd); unlink(filepath); return EXIT_FAILURE;
    }
    fprintf(stderr, "\n--- After ftruncate (Shrink to %ld) ---\n", (long)target_len);
    check_size(filepath);

    // 3. Use truncate to extend the file (using the path)
    target_len = 50;
    if (truncate(filepath, target_len) == -1) {
        perror("truncate extend failed");
        close(fd); unlink(filepath); return EXIT_FAILURE;
    }
    fprintf(stderr, "\n--- After truncate (Extend to %ld) ---\n", (long)target_len);
    check_size(filepath);

    close(fd);
    unlink(filepath); // Cleanup
    return EXIT_SUCCESS;
}
